#!/usr/bin/env bash
# CITINEL — vendor every runtime dependency locally.
#
# Run once from the project root:
#     bash vendor/fetch-vendor.sh
#
# After it completes the app makes ZERO network calls at load: React and all three font
# families are served from vendor/, the Google Fonts @import is commented out, and every
# page links the local font sheet.
#
# Idempotent. Re-run after a design-system update. `bash vendor/fetch-vendor.sh --revert`
# undoes the wiring and returns to the CDN (files stay on disk).
#
# Why this is a script and not committed binaries: it needs outbound network once, on a
# machine that has it. Nothing here is generated at page load.

set -euo pipefail
cd "$(dirname "$0")/.."
V=vendor
DS=$(find _ds -maxdepth 1 -type d -name 'citinel-design-system-*' | head -1)
FONTS_CSS="$DS/tokens/fonts.css"
GOOGLE_CSS='https://fonts.googleapis.com/css2?family=Michroma&family=Orbitron:wght@400..700&family=IBM+Plex+Sans:ital,wght@0,400;0,500;0,600;1,400&display=swap'
UA='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36'

# ── revert ────────────────────────────────────────────────────────────────────
if [ "${1:-}" = "--revert" ]; then
  sed -i.bak "s|^/\* vendored \*/ *@import|@import|" "$FONTS_CSS" || true
  sed -i.bak 's|^/\* vendored \*/ *||' "$FONTS_CSS" || true
  for f in *.dc.html; do
    sed -i.bak '/vendor\/resources\.js/d;/vendor\/fonts\.css/d' "$f"
  done
  rm -f ./*.bak "$DS"/tokens/*.bak
  echo "reverted to CDN loading. vendor/ files left in place."
  exit 0
fi

mkdir -p "$V/react" "$V/fonts"

# ── 1. React 18.3.1 + Babel (Babel is only used if a .jsx is ever imported) ───
echo "→ react"
curl -fsSL -o "$V/react/react.production.min.js"      https://unpkg.com/react@18.3.1/umd/react.production.min.js
curl -fsSL -o "$V/react/react-dom.production.min.js"  https://unpkg.com/react-dom@18.3.1/umd/react-dom.production.min.js
curl -fsSL -o "$V/react/babel.min.js"                 https://unpkg.com/@babel/standalone@7.29.0/babel.min.js

# support.js consults window.__resources to remap any CDN URL to a local path. This is its
# documented seam — support.js itself is never edited.
cat > "$V/resources.js" <<'JS'
/* CITINEL — vendored resource map. Generated by vendor/fetch-vendor.sh; do not hand-edit.
   support.js consults window.__resources before falling back to its CDN URLs, so this file
   is the whole mechanism. Delete it and the app reverts to unpkg. */
window.__resources = {
  "https://unpkg.com/react@18.3.1/umd/react.production.min.js":     "vendor/react/react.production.min.js",
  "https://unpkg.com/react-dom@18.3.1/umd/react-dom.production.min.js": "vendor/react/react-dom.production.min.js",
  "https://unpkg.com/@babel/standalone@7.29.0/babel.min.js":         "vendor/react/babel.min.js"
};
JS

# ── 2. Fonts: pull the CSS Google would serve a modern browser, take the woff2 urls ───
echo "→ fonts"
curl -fsSL -A "$UA" "$GOOGLE_CSS" -o "$V/fonts/_google.css"

grep -oE 'https://fonts\.gstatic\.com/[^)]+\.woff2' "$V/fonts/_google.css" | sort -u | while read -r url; do
  curl -fsSL -o "$V/fonts/$(basename "$url")" "$url"
done

# rewrite the sheet to point at the local copies
sed -E "s|https://fonts\.gstatic\.com/[^)]*/([^/)]+\.woff2)|\1|g" "$V/fonts/_google.css" > "$V/fonts.css"
# `sed 1i` is a GNU extension -- BSD/macOS sed requires the backslash-newline
# form and rejects this one-liner outright, aborting the whole script under
# set -e before the url() rewrite below ever runs. cat avoids the dialect
# split entirely and behaves identically on both.
printf '%s\n' '/* CITINEL — vendored web fonts. Generated by vendor/fetch-vendor.sh. */' \
  | cat - "$V/fonts.css" > "$V/fonts.css.tmp"
mv "$V/fonts.css.tmp" "$V/fonts.css"
# @font-face src is relative to the stylesheet, so the files sit beside it
sed -i.bak -E "s|url\(([A-Za-z0-9_.-]+\.woff2)\)|url(fonts/\1)|g" "$V/fonts.css"
rm -f "$V/fonts.css.bak"

# ── 3. Stop the remaining network call: silence the Google @import ────────────
if grep -q "^@import url('https://fonts.googleapis" "$FONTS_CSS"; then
  sed -i.bak "s|^@import url('https://fonts.googleapis|/* vendored */ /* @import url('https://fonts.googleapis|" "$FONTS_CSS"
  printf '%s\n' "*/" >> /dev/null   # the line is fully commented by the marker above
  rm -f "$FONTS_CSS.bak"
fi

# ── 4. Wire every page: resources map before support.js, local fonts after the DS sheet ──
echo "→ pages"
for f in *.dc.html; do
  grep -q 'vendor/resources.js' "$f" || \
    sed -i.bak 's|<script src="./support.js"></script>|<script src="vendor/resources.js"></script>\n<script src="./support.js"></script>|' "$f"
  grep -q 'vendor/fonts.css' "$f" || \
    sed -i.bak 's|\(<link rel="stylesheet" href="_ds/[^"]*tokens/fonts.css">\)|\1\n<link rel="stylesheet" href="vendor/fonts.css">|' "$f"
  rm -f "$f.bak"
done

echo
echo "vendored. verify with:  grep -rn 'unpkg\.com\|fonts\.googleapis' *.dc.html \"$FONTS_CSS\""
echo "expected: no uncommented matches. the app now loads with no outbound requests."
